-- Generated by execution/homework_sql.ts from docs/homework-2026-27/final/qaidah-hw7.json.
-- Loads homework 307 for 2026/27. Review, then apply with execution/apply_migration.ts.
-- Idempotent: re-running replaces the same papers again.

do $guard$ begin
  if exists (select 1 from submissions s join homeworks h on h.id = s.homework_id
             join auth.users u on u.id = s.student_id
             where h.number in (307) and coalesce(u.email, '') not like '%@bsms-demo.test') then
    raise exception 'a real student has work on a homework this load replaces; stop and ask';
  end if;
end $guard$;

-- Demo work on the replaced papers (answers, voice notes, attempts cascade).
delete from submissions where homework_id in (select id from homeworks where number in (307));
delete from questions where homework_id in (select id from homeworks where number in (307));

-- ── Homework 307: Shaddah (4 marks, 4 questions)
insert into homeworks (number, title, series, total_marks, is_graded, week_id, due_at, course_id, ordinal)
select 307, $q$Shaddah$q$, 'qaidah', 4, true, w.id, w.due_at, c.id, 7
  from weeks w, courses c where w.term_id = 1 and w.number = 7 and c.key = 'qaidah'
on conflict (number) do update set title = excluded.title, series = excluded.series, total_marks = excluded.total_marks,
  is_graded = true, course_id = excluded.course_id, ordinal = excluded.ordinal;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 1, 'text', 'manual', $q$Read the following words and record yourself. Read each letter with a shaddah twice: once with a sukūn, joined to the letter before it, then again with its vowel.$q$, 1, false, true, null, null, false
  from homeworks where number = 307;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 2, 'text', 'manual', $q$Read the following words and record yourself. Take your time over each shaddah.$q$, 1, false, true, null, null, false
  from homeworks where number = 307;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 3, 'text', 'manual', $q$Read the following words and record yourself. Take your time over each shaddah.$q$, 1, false, true, null, null, false
  from homeworks where number = 307;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 4, 'text', 'manual', $q$This is meant to push you, but please remember the concepts we've covered already, such as ghunnah. Read the following words and record yourself.$q$, 1, false, true, null, null, false
  from homeworks where number = 307;

-- Audio needs questions.media (migration 0048); skipped until it exists.
do $media$ begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'questions' and column_name = 'media') then
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw7-1.jpg","alt":"Twelve short words with a shaddah","width":960,"height":279}]}$q$::jsonb where position = 1 and homework_id = (select id from homeworks where number = 307);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw7-2.jpg","alt":"Twenty words with a shaddah","width":960,"height":552}]}$q$::jsonb where position = 2 and homework_id = (select id from homeworks where number = 307);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw7-3.jpg","alt":"Fifteen words with a shaddah","width":960,"height":409}]}$q$::jsonb where position = 3 and homework_id = (select id from homeworks where number = 307);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw7-4.jpg","alt":"Five longer words with a shaddah","width":960,"height":139}]}$q$::jsonb where position = 4 and homework_id = (select id from homeworks where number = 307);
  end if;
end $media$;

select number, title, total_marks, (select count(*) from questions q where q.homework_id = h.id) as questions
  from homeworks h where number in (307) order by number;
